/*
 * Это не jQuery. Старого сайта на этом адресе больше нет (замена 04.10.2026),
 * но браузеры, где он когда-то открывался, ещё неделями показывают его
 * сохранённую копию: старый сайт не говорил браузеру, сколько её хранить.
 * Такая копия подгружает этот файл — и он отправляет человека на новую
 * страницу мимо кэша. Новый сайт этот файл не использует.
 */
(function () {
  try {
    if (/[?&]fresh=/.test(location.search)) return;
    var path = location.pathname;
    var target = /about/.test(path) ? '/about/'
      : /contact/.test(path) ? '/contact/'
      : /services/.test(path) ? '/services/'
      : '/';
    location.replace('https://julialyapina.ru' + target + '?fresh=' + Date.now());
  } catch (e) {}
})();
